package com.lolfm.simulator;import com.lolfm.domain.*;import java.util.List;
final class LateGameTestSupport{private LateGameTestSupport(){}static TeamState team(String name){return new TeamState(name,List.of(player(name+"-TOP",Position.TOP),player(name+"-JUNGLE",Position.JUNGLE),player(name+"-MID",Position.MID),player(name+"-ADC",Position.ADC),player(name+"-SUPPORT",Position.SUPPORT)));}static PlayerState player(String n,Position p){return new PlayerState(n,p,new PlayerAttributes(14,14,14,14),500);}static GameState state(){return new GameState(team("BLUE"),team("RED"),true,true,true,true,true,true);}static void midGameAt(GameState s,int time){s.advanceTimeSeconds(LanePhaseRuleConfig.MIDGAME_TRANSITION_SECONDS);s.getLanePhaseState().transitionIfDue(s.getCurrentTimeSeconds());if(time>s.getCurrentTimeSeconds())s.advanceTimeSeconds(time-s.getCurrentTimeSeconds());}static void destroyThroughInhibitorTower(GameState s,TeamSide defending,Lane lane){LaneStructureState x=s.getMapState().getLaneState(defending,lane);x.destroy(TowerTier.OUTER,s.getCurrentTimeSeconds(),defending.opposite(),StructureActionSource.MACRO_PLAY);x.destroy(TowerTier.INNER,s.getCurrentTimeSeconds(),defending.opposite(),StructureActionSource.MACRO_PLAY);x.destroy(TowerTier.INHIBITOR,s.getCurrentTimeSeconds(),defending.opposite(),StructureActionSource.MACRO_PLAY);}}
